    @staticmethod
    def now(tz=None): return FakeDateTime._now
R.datetime=FakeDateTime
def now(): return FakeDateTime._now
def advance(ms): FakeDateTime._now+=timedelta(milliseconds=ms)

ALLOWED={"accepted":{"processing","failed"},"processing":{"completed","failed"},"completed":set(),"failed":set()}

def run(seed):
    random.seed(seed)
    store=R.RequestStore(":memory:")
    N=4
    rids=[store.submit("t",f"s{i}",["email"],f"k{i}"])["request_id"] for i in range(N)]
    # model: status per rid; live token set per rid with expiry
    status={r:"accepted" for r in rids}
    live={r:set() for r in rids}  # (token,expiry) for open attempts not closed
    for step in range(500):
        cur=now(); op=random.random(); rid=random.choice(rids)
        if op<0.26:
            c=store.claim_next("t","w",random.choice([1,2,3]))
            if c is not None:
                tgt=c["request_id"]; exp=datetime.fromisoformat(c["lease_expires_at"].replace("Z","+00:00"))
                # a claim that supersedes must not occur while a live open lease exists
                if any(cur<=e for _t,e in live[tgt]):
                    return f"s{step} DOUBLE LEASE {tgt} live={live[tgt]} cur={cur}"
                # model transition
                if status[tgt]=="accepted": status[tgt]="processing"
                live[tgt]={(c["claim_token"],exp)}
        elif op<0.42:
            for tok,exp in list(live[rid]):
                try:
                    r=store.finish_claim("t",rid,tok,random.choice(["completed","failed"]))
                    if not(cur<=exp): return f"s{step} FINISH after expiry"
                    status[rid]=r["status"]; live[rid]=set()
                except R.ClaimConflict: pass
                break
        elif op<0.52:
            # transition to a legal random target
            tgt=random.choice(list(ALLOWED[status[rid]]) or [status[rid]])
            try:
                store.transition("t",rid,tgt); status[rid]=tgt
                if tgt in ("completed","failed"): live[rid]=set()
            except R.InvalidStatusTransition: pass
        elif op<0.74:
            rec=store.reconcile_execution("t",rid)
            # CORE INVARIANTS
            genuinely_live = any(cur<=e for _t,e in live[rid]) and status[rid]=="processing"
            if genuinely_live and rec["status"]!="processing":
                return f"s{step} WRONGFUL CONVERGE {rid} ->{rec['status']} while live {live[rid]} cur={cur}"
            # if processing and NOT live, it must converge (failed or existing terminal)
            if status[rid]=="processing" and not any(cur<=e for _t,e in live[rid]):
