            if rec["status"] in ("completed","failed"): live[rid]=set()
        elif op<0.82:
            store.reconcile_batch("t",limit=1000)
            for r in rids:
                st=store.get_status("t",r)["status"]; status[r]=st
                if st in ("completed","failed"): live[r]=set()
        advance(random.choice([0,1,250,800,1000,1001,1400,2100,4000]))
    return None

